const fs = require("node:fs");
const path = require("node:path");
const prettier = require("prettier");
const { ORIGIN, STATIC_PAGES } = require("./registry");

const ROOT = path.resolve(__dirname, "../..");
const MARKER =
  "<!-- Generated by npm run site:generate. Edit site/ instead. -->";
const REQUIRED_TEXT = [
  "slug",
  "name",
  "location",
  "theme",
  "icon",
  "dek",
  "description",
  "takeaway",
];
const FIELDS = new Set([
  "scenarioId",
  ...REQUIRED_TEXT,
  "startingYear",
  "durationYears",
  "setup",
  "decisions",
  "related",
  "kind",
]);

function fail(message) {
  throw new Error(`Site content: ${message}`);
}

function text(value, label) {
  if (typeof value !== "string" || !value.trim())
    fail(`${label} must be nonempty text`);
}

function validatePages(pages, { publicDir = path.join(ROOT, "public") } = {}) {
  if (!Array.isArray(pages) || !pages.length)
    fail("scenarios.json must contain a nonempty array");
  const ids = new Set();
  const slugs = new Set();
  for (const page of pages) {
    if (!page || typeof page !== "object" || Array.isArray(page))
      fail("each scenario must be an object");
    const label = `scenario ${page.scenarioId}`;
    for (const key of Object.keys(page))
      if (!FIELDS.has(key)) fail(`${label} has unknown field ${key}`);
    if (!Number.isSafeInteger(page.scenarioId) || page.scenarioId < 0)
      fail(`${label} needs a nonnegative integer scenarioId`);
    if (ids.has(page.scenarioId))
      fail(`duplicate scenarioId ${page.scenarioId}`);
    ids.add(page.scenarioId);
    for (const field of REQUIRED_TEXT) text(page[field], `${label}.${field}`);
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(page.slug))
      fail(`${label} needs a lowercase, hyphen-separated slug`);
    if (slugs.has(page.slug)) fail(`duplicate slug ${page.slug}`);
    slugs.add(page.slug);
    if (!Number.isSafeInteger(page.startingYear) || page.startingYear < 1)
      fail(`${label}.startingYear must be a positive integer`);
    if (!Number.isFinite(page.durationYears) || page.durationYears <= 0)
      fail(`${label}.durationYears must be positive`);
    if (page.kind !== undefined && page.kind !== "campaign")
      fail(`${label}.kind must be campaign when supplied`);
    if (!Array.isArray(page.setup) || !page.setup.length)
      fail(`${label}.setup needs at least one paragraph`);
    page.setup.forEach((paragraph) => text(paragraph, `${label}.setup`));
    if (!Array.isArray(page.decisions) || !page.decisions.length)
      fail(`${label}.decisions needs at least one decision`);
    for (const decision of page.decisions) {
      if (!decision || typeof decision !== "object" || Array.isArray(decision))
        fail(`${label}.decisions must contain objects`);
      text(decision.title, `${label}.decision.title`);
      text(decision.body, `${label}.decision.body`);
      if (Object.keys(decision).some((key) => !["title", "body"].includes(key)))
        fail(`${label}.decision has an unknown field`);
    }
    if (
      !Array.isArray(page.related) ||
      !page.related.length ||
      new Set(page.related).size !== page.related.length
    )
      fail(`${label}.related needs distinct scenario IDs`);
    // Keep authored assets within public/images. URL delimiters and traversal are not filenames.
    if (
      !/^\/images\/[a-zA-Z0-9 /_-]+\.svg$/.test(page.icon) ||
      page.icon.includes("//") ||
      !fs
        .statSync(path.join(publicDir, page.icon), { throwIfNoEntry: false })
        ?.isFile()
    )
      fail(`${label}.icon must reference an existing SVG under /images/`);
  }
  for (const page of pages)
    for (const id of page.related)
      if (!ids.has(id) || id === page.scenarioId)
        fail(`scenario ${page.scenarioId} has invalid related scenario ${id}`);
  return pages;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => {
    return {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    }[character];
  });
}

function jsonLd(value) {
  // JSON is embedded in an HTML script element, where a literal </script> ends the element.
  return JSON.stringify(value).replace(/[<>&\u2028\u2029]/g, (character) => {
    return `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`;
  });
}

const scenarioPath = (page) => `/scenarios/${page.slug}.html`;
const playUrl = (page) =>
  page.kind === "campaign"
    ? "/?campaign=legacy"
    : `/?scenario=${page.scenarioId}`;
const iconUrl = (page) =>
  page.icon.split("/").map(encodeURIComponent).join("/");

function createContext(pages) {
  const byId = new Map(pages.map((page) => [page.scenarioId, page]));
  return {
    origin: ORIGIN,
    escapeHtml,
    jsonLd,
    scenarioPath,
    playUrl,
    iconUrl,
    relatedPages: (page) => page.related.map((id) => byId.get(id)),
    metadata: (page) => ({
      title: page
        ? `${page.name} — Electrify scenario`
        : "Scenarios — Electrify electricity strategy game",
      description: page
        ? page.description
        : "Choose your next grid challenge in Electrify. Manage an island utility, prepare for extreme weather, or build a company across generations. Free to play in your browser.",
      canonical: `${ORIGIN}${page ? scenarioPath(page) : "/scenarios.html"}`,
      image: `${ORIGIN}/images/gameplay-preview.png`,
    }),
  };
}

function sitemap(paths) {
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${paths.map((pathname) => `  <url>\n    <loc>${escapeHtml(ORIGIN + pathname)}</loc>\n  </url>`).join("\n")}
</urlset>
`;
}

function crawlerGuide(pages) {
  return `# Electrify

> A free electricity strategy game about running a utility: build power plants, balance supply and demand, and manage reliability, costs, and emissions.

## Start here

- [About the game](${ORIGIN}/about.html): Background, sources, and contact.
- [Scenario directory](${ORIGIN}/scenarios.html): Every official challenge and Legacy campaign chapter, with links to play.
- [How Electrify plays](${ORIGIN}/power-grid-simulator.html): A guide for new players.
- [Classroom resources](${ORIGIN}/classroom.html): Lesson plan and printable worksheet.

## Official scenarios

These pages describe playable simulations. Legacy chapters belong to one continuing campaign, and their play links open campaign setup.

${pages.map((page) => `- [${page.name.replace(/[[\]\r\n]/g, "")}](${ORIGIN}${scenarioPath(page)}): ${page.dek.replace(/[\r\n]/g, " ")}`).join("\n")}
`;
}

async function buildSite({ root = ROOT, pages } = {}) {
  const publicDir = path.join(root, "public");
  pages = validatePages(
    pages ||
      JSON.parse(fs.readFileSync(path.join(root, "site/scenarios.json"))),
    { publicDir },
  );
  for (const page of STATIC_PAGES) {
    const target = path.join(
      publicDir,
      page.path === "/" ? "index.html" : page.path,
    );
    if (!fs.statSync(target, { throwIfNoEntry: false })?.isFile())
      fail(`registered page ${page.path} does not exist`);
  }
  const { renderScenarioPage, renderScenarioIndex } = require(
    path.join(root, "site/templates/pages.js"),
  );
  const context = createContext(pages);
  const output = new Map();
  const format = async (html) =>
    prettier.format(
      html.replace(/<!doctype html>/i, `<!doctype html>\n${MARKER}`),
      {
        parser: "html",
        printWidth: 80,
        trailingComma: "all",
        endOfLine: "lf",
      },
    );
  output.set(
    "public/scenarios.html",
    await format(renderScenarioIndex(pages, context)),
  );
  for (const page of pages)
    output.set(
      `public${scenarioPath(page)}`,
      await format(renderScenarioPage(page, context)),
    );
  output.set(
    "public/sitemap.xml",
    sitemap([
      ...STATIC_PAGES.map((page) => page.path),
      "/scenarios.html",
      ...pages.map(scenarioPath),
    ]),
  );
  output.set("public/llms.txt", crawlerGuide(pages));
  return output;
}

async function generate({ root = ROOT, check = false } = {}) {
  const output = await buildSite({ root });
  const changed = [];
  for (const [relative, contents] of output) {
    const target = path.join(root, relative);
    const current = fs.existsSync(target)
      ? fs.readFileSync(target, "utf8")
      : "";
    if (current === contents) continue;
    changed.push(relative);
    if (!check) {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, contents);
    }
  }
  const directory = path.join(root, "public/scenarios");
  if (fs.existsSync(directory))
    for (const entry of fs.readdirSync(directory)) {
      const relative = `public/scenarios/${entry}`;
      if (!entry.endsWith(".html") || output.has(relative)) continue;
      const target = path.join(directory, entry);
      if (!fs.readFileSync(target, "utf8").includes(MARKER))
        fail(
          `unmanaged file ${relative}; move it before generating scenario pages`,
        );
      changed.push(relative);
      if (!check) fs.unlinkSync(target);
    }
  if (check && changed.length)
    throw new Error(
      `Generated site pages are stale: ${changed.join(", ")}. Run npm run site:generate and include the outputs.`,
    );
  return { files: output.size, changed };
}

if (require.main === module) {
  const args = process.argv.slice(2);
  if (args.some((arg) => arg !== "--check")) {
    console.error("Usage: node scripts/site/generate.js [--check]");
    process.exitCode = 1;
  } else {
    generate({ check: args.includes("--check") })
      .then(({ files, changed }) => {
        process.stdout.write(
          args.includes("--check")
            ? `Site pages are current (${files} files).\n`
            : `Generated site pages (${changed.length} changed, ${files} files).\n`,
        );
      })
      .catch((error) => {
        console.error(error.message);
        process.exitCode = 1;
      });
  }
}

module.exports = {
  MARKER,
  validatePages,
  escapeHtml,
  jsonLd,
  scenarioPath,
  playUrl,
  iconUrl,
  createContext,
  buildSite,
  generate,
};
